/// What game::Detect checks: functions whose first 16 bytes are the same in every build, at each build's address.
pub struct Sig {
    pub exe: Option<fn(&Exe) -> usize>,
    pub ls3d: Option<fn(&Ls3d) -> usize>,
    pub bytes: [u8; 16],
}
fn sig_exe_testLine(e: &Exe) -> usize {
    e.testLine
}
fn sig_exe_vehicleExternalForce(e: &Exe) -> usize {
    e.vehicleExternalForce
}
fn sig_exe_actorSetPos(e: &Exe) -> usize {
    e.actorSetPos
}
fn sig_exe_sceneMoved(e: &Exe) -> usize {
    e.sceneMoved
}
fn sig_exe_frameSetPos(e: &Exe) -> usize {
    e.frameSetPos
}
fn sig_ls3d_frameSlot18(l: &Ls3d) -> usize {
    l.frameSlot18
}
fn sig_ls3d_frameSlot38(l: &Ls3d) -> usize {
    l.frameSlot38
}
fn sig_ls3d_frameSlot3C(l: &Ls3d) -> usize {
    l.frameSlot3C
}
fn sig_ls3d_materialOpen(l: &Ls3d) -> usize {
    l.materialOpen
}
